Definition P_INS_RET1 : Z := 0x35590.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition ins_frame (m : mem) (sp ra s0 s1 : word) (j8 : list byte) : Prop :=
  rw_cells usegs m (bv_unsigned sp + -32) [CB 8 j8; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition ins_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa f np vp ecA : Z) (name value : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j8 j32 p5 msk vp',
    ms' = MS (mkR (Z_to_bv 64 P_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2
                  (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 (elem_block_size name (trim value))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f) (Z_to_bv 64 (zlength (trim value))) s4 (Z_to_bv 64 p5) (Z_to_bv 64 msk) s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (ecA, ecA + 24)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -128)
    /\ ins_frame m' sp ra s0 s1 j8
    /\ tc_frame m' (Z_to_bv 64 (bv_unsigned sp + -32)) (Z_to_bv 64 P_INS_RET1) (Z_to_bv 64 Fa) (Z_to_bv 64 ecA) s2 s3 s4 s5 s6 j32
    /\ rw_cells usegs m' ecA (ErrCodeCells EC_clear)
    /\ Z.land msk p5 = vp' /\ 0 <= p5 < 2^64 /\ 0 <= msk < 2^64
    /\ bytes_at usegs m' vp' (trim value)
    /\ ((vp <= vp' /\ vp' + zlength (trim value) <= vp + zlength value) \/ (vp' = 0 /\ trim value = [])).

Definition INS_SEG1_STACK : Z := 128.   (* [comment removed for export] *)

Definition ins_seg1_stmt : Prop := forall (Fa f np vp ecA : Z) (name value : list byte) (E0 : ecv) (lo : Z)
