    (F : bvmap 5 word) fc (m : mem),
  bytes_at usegs m vp value -> rw_cells usegs m ecA (ErrCodeCells E0) ->
  zlength name <= 65533 -> zlength value <= 65533 -> vp + zlength value < 2^64 ->
  (vp + zlength value <= lo \/ bv_unsigned sp <= vp) ->
  bv_unsigned sp <= ecA -> ecA + 24 <= 2^64 -> (vp + zlength value <= ecA \/ ecA + 24 <= vp) ->
  stk usegs m lo (bv_unsigned sp) -> lo + INS_SEG1_STACK <= bv_unsigned sp -> hceil <= lo ->
  (0 < zlength value -> 0 < vp) ->                                           (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (ins_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa f np vp ecA name value lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 Fa) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ecA) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FIELDS_INSERT) fc None m (seg_rom usegs)).
