(* [comment removed for export] *)
Definition ins_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa A f : Z) (name tv : list byte) (L : list Z) (em : gmap Z elt) (ecA lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' pad tl S' L' ns' ls',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch ((A + 48, A + elem_block_size name tv) :: insW lo (bv_unsigned sp) Fa (A :: L)) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ FieldsC m' Fa S' L' ns' ls' (<[A := mkElt f name tv pad tl]> em) /\ (A + 16) ∈ S' /\ A ∈ L'
    /\ zlength tl = elem_block_size name tv - 60 - zlength name - zlength tv
    /\ rw_cells usegs m' ecA (ErrCodeCells EC_clear).

Definition INS_SEG2_STACK : Z := 272.   (* [comment removed for export] *)

Definition ins_seg2_stmt : Prop := forall (Fa A f np vp' p5 msk ecA : Z) (name tv : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt)
    (lo : Z) (j8 j32 junkB : list byte)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 s4x : word)
    (F : bvmap 5 word) fc (m : mem),
  ins_frame m sp ra s0 s1 j8 ->
  tc_frame m (Z_to_bv 64 (bv_unsigned sp + -32)) (Z_to_bv 64 P_INS_RET1) (Z_to_bv 64 Fa) (Z_to_bv 64 ecA) s2 s3 s4 s5 s6 j32 ->
  rw_cells usegs m A [CB (Z.to_nat (elem_block_size name tv)) junkB] -> rblock_range A (elem_block_size name tv) ->
  bytes_at usegs m np name -> bytes_at usegs m vp' tv ->
  zlength name <= 65533 -> zlength tv <= 65533 -> 0 <= f < 2^16 ->
  (np + zlength name <= A \/ A + elem_block_size name tv <= np) -> (vp' + zlength tv <= A \/ A + elem_block_size name tv <= vp') ->
  (np + zlength name <= lo \/ bv_unsigned sp <= np) -> (vp' + zlength tv <= lo \/ bv_unsigned sp <= vp') ->
  rw_cells usegs m ecA (ErrCodeCells EC_clear) -> bv_unsigned sp <= ecA -> ecA + 24 <= 2^64 -> (ecA + 24 <= Fa \/ Fa + 48 <= ecA) ->
  FieldsC m Fa S L ns ls em ->
  (forall e' d', em !! e' = Some d' -> A + elem_block_size name tv <= e' \/ e' + esize d' <= A) ->
  stk usegs m lo (bv_unsigned sp + -128) -> lo + INS_SEG2_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= Fa ->
  Z.land msk p5 = vp' -> 0 <= p5 < 2^64 -> 0 <= msk < 2^64 ->
  bv_unsigned sp mod 16 = 0 ->                                                  (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (ins_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa A f name tv L em ecA lo m)
    (MS (mkR (Z_to_bv 64 P_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2
              (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 f) (Z_to_bv 64 (zlength tv)) s4x (Z_to_bv 64 p5) (Z_to_bv 64 msk) s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_TCNE_RET1) fc None m (seg_rom usegs)).
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.option Sort Prop.

