(* [comment removed for export] *)
Lemma FieldsC_transport_hi : forall W m m' Fa S L ns ls em,
  FieldsC m Fa S L ns ls em -> munch W m m' -> wmono usegs m m' ->
  Forall (fun iv : Z * Z => hceil <= fst iv /\ (snd iv <= Fa \/ Fa + 48 <= fst iv)) W ->
  FieldsC m' Fa S L ns ls em.
Proof.
  intros W m m' Fa S L ns ls em FC MU WM FW.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LEQ & EOK & HH & HB & AL).
  assert (DJ : forall a n, (a + n <= hceil \/ (Fa <= a /\ a + n <= Fa + 48)) -> disjoint_from W a n).
  { intros a n Ha. clear -FW Ha. induction W as [|[u v] W IH]; [exact I|]. cbn. pose proof (Forall_inv FW) as K. cbn in K.
    split; [lia| apply IH; exact (Forall_inv_tail FW)]. }
  split.
  { eapply NSCells_transport; [exact NC| exact MU| exact WM|]. intros a nd La. apply DJ.
    destruct (FieldsC_node_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _ & P & _ & R)]; [right; lia|]. pose proof (esize_ge d). left; lia. }
  split.
  { eapply LSCells_transport; [exact LC| exact MU| exact WM|]. intros a n La. apply DJ.
    destruct (FieldsC_lnode_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _ & P & _ & R)]; [right; lia|]. pose proof (esize_ge d). left; lia. }
  split.
  { eapply EMCells_transport; [exact EC| exact MU| exact WM|]. intros e d Ld. apply DJ.
    pose proof (em_ok_range _ _ _ EOK Ld) as (P & _ & R & _). pose proof (esize_ge d). left; lia. }
  split; [exact OK|]. split; [exact SO|]. split; [exact DL|]. split; [exact SL|]. split; [exact LEQ|].
  split; [exact EOK|]. split; [exact HH|]. split; [exact HB| exact AL].
Qed.

