Lemma disjoint_cons : forall lo hi W a n, (a + n <= lo \/ hi <= a) -> disjoint_from W a n -> disjoint_from ((lo, hi) :: W) a n.
Proof. intros. cbn. split; fast_assumption. Qed.

Definition INS_STACK : Z := 128 + ROPNEW_STACK.   (* [comment removed for export] *)

Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition ins_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (Fa f ecA : Z) (name value : list byte) (L : list Z) (em : gmap Z elt)
      (lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p : bptr) (A : Z) pad tl S' L' ns' ls',
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range A (elem_block_size name (trim value))
      /\ hs_RHEAP H s' ((p, A, elem_block_size name (trim value)) :: LB) m'
      /\ FieldsC m' Fa S' L' ns' ls' (<[A := mkElt f name (trim value) pad tl]> em) /\ (A + 16) ∈ S' /\ A ∈ L'
      /\ FieldsOwn ((p, A, elem_block_size name (trim value)) :: LB) (<[A := mkElt f name (trim value) pad tl]> em)
      /\ rw_cells usegs m' ecA (ErrCodeCells EC_clear)
      /\ xpres LB (bv_unsigned sp) ((ecA, ecA + 24) :: (Fa, Fa + 48) :: elemsW L) m m'.

  Definition ins_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (Fa f np vp ecA : Z) (name value : list byte) (E0 : ecv)
           (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo B : Z) (errv : word),
      a0 = Z_to_bv 64 Fa -> a1 = Z_to_bv 64 f -> a2 = Z_to_bv 64 np -> a3 = Z_to_bv 64 (zlength name) ->
      a4 = Z_to_bv 64 vp -> a5 = Z_to_bv 64 (zlength value) -> a6 = Z_to_bv 64 ecA ->
      FieldsC m Fa S L ns ls em -> FieldsOwn LB em ->
      bytes_at usegs m np name -> rclient_range LB (bv_unsigned sp) np (zlength name) ->
      bytes_at usegs m vp value -> rclient_range LB (bv_unsigned sp) vp (zlength value) -> vp + zlength value < 2^64 ->
      zlength name <= 65533 -> zlength value <= 65533 -> 0 <= f < 2^16 ->
      rw_cells usegs m ecA (ErrCodeCells E0) -> bv_unsigned sp <= ecA -> ecA + 24 <= B ->
      (ecA + 24 <= Fa \/ Fa + 48 <= ecA) -> (np + zlength name <= ecA \/ ecA + 24 <= np) -> (vp + zlength value <= ecA \/ ecA + 24 <= vp) ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + (zlength name + zlength value + 67) <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> Fa + 48 <= B -> B <= 2^64 ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - INS_STACK -> bv_unsigned sp <= Fa ->
